def test_website_and_links_present():
    """Verifies that both 'links' and 'website' are included in 'ids_links' when present."""
    results_info = {"username": "test"}
    extracted_ids_data = {
        "links": "['https://example.com/a', 'https://example.com/b']",
        "website": "https://example.com/w"
    }
    new_usernames = {"alice": "username"}
    result = update_results_info(results_info, extracted_ids_data, new_usernames)
    assert result["ids_usernames"] == {"alice": "username"}
    assert "https://example.com/w" in result["ids_links"]
    assert "https://example.com/a" in result["ids_links"]

